    public function __construct(string $code, string $name) { $this->code = $code; $this->name = $name; }

    public function id(): ?int { return $this->id; }
    public function code(): string { return $this->code; }
    public function name(): string { return $this->name; }
    public function offPeakStart(): ?string { return $this->offPeakStart; }
    public function offPeakEnd(): ?string { return $this->offPeakEnd; }
    public function offPeakMultiplier(): ?string { return $this->offPeakMultiplier; }

    public function setOffPeak(?string $windowStart, ?string $windowEnd, ?string $multiplier): void
    {
        $this->offPeakStart = $windowStart;
        $this->offPeakEnd = $windowEnd;
        $this->offPeakMultiplier = $multiplier;
    }

    public function offPeakPolicy(): ?OffPeakPolicy
