namespace App\Application;

final class PriceCatalogImporter
{
    public function __construct(
        private readonly EntityManagerInterface $em,
        private readonly PricesFileParser $parser,
    ) {}

    public function import(string $file): ImportSummary
    {
        $data = $this->parser->parseFile($file);

        $providers = 0; $models = 0; $prices = 0;

        $this->em->transaction(function () use ($data, &$providers, &$models, &$prices) {
            $modelMap = []; // providerCode . "\x00" . code => Model
            foreach ($data->providers as $p) {
                $entity = $this->providers()->findByCode($p->code) ?? new Provider($p->code, $p->name);
                $entity->setName($p->name);
                $entity->setOffPeak($p->windowStart, $p->windowEnd, $p->multiplier);
                $this->em->persist($entity);
                $providers++;
            }
            foreach ($data->models as $m) {
                $key = ...;
                $entity = $modelMap[$key] ?? $this->models()->findByProviderCodeAndCode($m->provider, $m->code);
                if ($entity === null) {
                    $provider = $this->providers()->findByCode($m->provider)
                        ?? throw new BillingException("Provider not found: {$m->provider} (referenced from model {$m->code})");
                    $entity = new Model($provider, $m->code);
                    $this->em->persist($entity);
                }
                $modelMap[$key] = $entity;
                $models++;
            }
            foreach ($data->prices as $pr) {
                $key = $pr->provider . "\x00" . $pr->model;
                $model = $modelMap[$key] ?? null;
                if ($model === null) {
                    $model = $this->models()->findByProviderCodeAndCode($pr->provider, $pr->model)
                        ?? throw new BillingException("Model not found: {$pr->provider}/{$pr->model}");
                }
                $entity = $this->prices()->findByModelAndValidFrom($model, $pr->validFrom);
                if ($entity === null) {
                    $entity = new Price($model, $pr->validFrom, $pr->currency, $pr->unit, $pr->rates);
                    $this->em->persist($entity);
                } else {
                    $entity->update($pr->currency, $pr->unit, $pr->rates);
                }
                $prices++;
            }
        });

        return new ImportSummary($providers, $models, $prices);
    }
}
```
