final class UsageEventImporter
{
    public function __construct(private readonly EntityManagerInterface $em) {}

    public function import(string $file): UsageImportSummary
    {
        if (!is_file($file)) throw new BillingException("File not found: {$file}");
        $raw = file_get_contents($file);
        if ($raw === false) throw new BillingException("Cannot read file: {$file}");

        $rows = [];
        $duplicates = 0;
        $seenInFile = [];
        $lineNo = 0;
        foreach (preg_split('/\R/', $raw) as $line) {
            $lineNo++;
            $trimmed = trim($line);
            if ($trimmed === '') continue;
            $data = $this->parseLine($trimmed, $lineNo);
            $key = $data['provider']."\x00".$data['providerRequest'];
            if (isset($seenInFile[$key])) { $duplicates++; continue; }
            $seenInFile[$key] = true;
            $rows[] = $data;
        }

        // existing in DB
        $existingKeys = $this->existingKeys(array_keys($seenInFile)); // array of p, r values
        $created = 0;
        foreach ($rows as $r) {
            if (isset($existingKeys[$r['provider']."\x00".$r['providerRequest']])) { $duplicates++; continue; }
            $event = UsageEvent::create(...);
            $this->em->persist($event);
            $created++;
        }
        $this->em->flush();
        return new UsageImportSummary(count($rows) + $duplicates, $created, $duplicates);
    }
}
```
parseLine returns a validated array; on any problem, throws BillingException including the line number.

