**PricingCalculator:**

```php
final class PricingCalculator
{
    private const PER_MILLION = '1000000';

    public function price(Price $row, TokenUsage $tokens, ?OffPeakPolicy $offPeak = null, ?\DateTimeImmutable $tsUtc = null): string
    {
        $cost = match ($row->unit()) {
            Price::UNIT_PER_TOKEN => $this->sumPerKind($row->rates(), $tokens),
            Price::UNIT_UNIFIED => Money::div(
                Money::mul((string) $tokens->total(), $this->rate($row->rates(), 'any')),
                self::PER_MILLION,
            ),
            default => throw new BillingException("Unknown unit: {$row->unit()}"),
        };

        if ($offPeak !== null && $tsUtc !== null && $offPeak->applies($tsUtc)) {
            $cost = Money::mul($cost, $offPeak->multiplier());
        }

        return Money::roundHalfUp($cost);
    }

    private function sumPerKind(array $rates, TokenUsage $tokens): string
    {
        $sum = '0';
        foreach (['input' => $tokens->input(), 'output' => $tokens->output(), 'cache_read' => $tokens->cacheRead(), 'cache_write' => $tokens->cacheWrite()] as $kind => $count) {
            $sum = Money::add($sum, Money::div(Money::mul((string) $count, $this->rate($rates, $kind)), self::PER_MILLION));
        }
        return $sum;
    }

    private function rate(array $rates, string $kind): string
    {
        if (!isset($rates[$kind]) || !is_scalar($rates[$kind])) {
            throw new BillingException("Price has no rate '{$kind}'");
        }
        return (string) $rates[$kind];
    }
}
