```php
final class OffPeakPolicy
{
    private int $startMinutes;
    private int $endMinutes;

    public function __construct(private readonly string $windowStart, private readonly string $windowEnd, private readonly string $multiplier)
    {
        $this->startMinutes = self::toMinutes($windowStart, 'window_start');
        $this->endMinutes = self::toMinutes($windowEnd, 'window_end');
        if (preg_match(self::DECIMAL, $multiplier) !== 1) throw new BillingException(...); // non-negative decimal
    }

    public static function toMinutes(string $hhmm, string $field): int {
        if (preg_match('/^([01]\d|2[0-3]):([0-5]\d)$/', $hhmm, $m) !== 1) {
            throw new BillingException("{$field}: expected HH:MM format, got '{$hhmm}'");
        }
        return ((int) $m[1]) * 60 + (int) $m[2];
    }

    public function applies(\DateTimeImmutable $tsUtc): bool
    {
        $minute = ((int) $tsUtc->format('G')) * 60 + (int) $tsUtc->format('i');
        if ($this->startMinutes === $this->endMinutes) return false;
        if ($this->startMinutes < $this->endMinutes) {
            return $minute >= $this->startMinutes && $minute < $this->endMinutes;
        }
        return $minute >= $this->startMinutes || $minute < $this->endMinutes; // window crossing midnight
    }

    public function multiplier(): string { return $this->multiplier; }
}
