<?php

declare(strict_types=1);

namespace App\Domain\Billing;

use App\Domain\Exception\BillingException;

/**
 * Exact decimal arithmetic for monetary amounts (bcmath).
 *
 * - all operations — without rounding (with a precision margin);
 * - the only rounding — roundHalfUp() on the amount of an event;
 * - float is not used anywhere.
 */
final class Money
{
    /** The scale at which the final amount of an event is reported. */
    public const MONEY_SCALE = 6;

    /** The working scale for intermediate computations (per the spec, at least 16). */
    private const WORK_SCALE = 24;

    private function __construct()
    {
    }

    public static function add(string $a, string $b): string
    {
        return bcadd($a, $b, self::WORK_SCALE);
    }

    public static function sub(string $a, string $b): string
    {
        return bcsub($a, $b, self::WORK_SCALE);
    }

    public static function mul(string $a, string $b): string
    {
        return bcmul($a, $b, self::WORK_SCALE);
    }

    public static function div(string $a, string $b): string
    {
        if (bccomp($b, '0', self::WORK_SCALE) === 0) {
            throw new BillingException('Division by zero in monetary amount');
        }

        return bcdiv($a, $b, self::WORK_SCALE);
    }

    /**
     * Half-up rounding: for non-negative numbers, 0.0000005 -> 0.000001 (round away from zero).
     */
    public static function roundHalfUp(string $value, int $scale = self::MONEY_SCALE): string
    {
        if ($scale < 0) {
            throw new BillingException('Rounding scale cannot be negative');
        }

        $negative = str_starts_with($value, '-');
        $abs = $negative ? substr($value, 1) : $value;

        // bcadd truncates the result to the scale; adding half of the last digit
        // gives exactly the "half-away-from-zero" rule for non-negative numbers.
        $half = '0.' . str_repeat('0', $scale) . '5';
        $rounded = bcadd($abs, $half, $scale);

        return ($negative && bccomp($rounded, '0', $scale) > 0) ? '-'.$rounded : $rounded;
    }

    /**
     * Display the amount with exactly $scale digits after the dot (no rounding:
     * the value is assumed to already be an exact multiple of the last digit).
     */
    public static function format(string $value, int $scale = self::MONEY_SCALE): string
    {
        return bcadd($value, '0', $scale);
    }
}
