<?php

declare(strict_types=1);

namespace App\Domain\Billing;

use App\Entity\Price;
use DateTimeImmutable;

/**
 * Price selection per task rule #1: the row with the maximum valid_from that is ≤ the event's moment.
 */
final class PriceSelection
{
    private function __construct()
    {
    }

    /**
     * @param iterable<Price> $rows
     */
    public static function best(DateTimeImmutable $eventTime, iterable $rows): ?Price
    {
        $best = null;

        foreach ($rows as $row) {
            if ($row->validFrom() > $eventTime) {
                continue; // row not in effect yet at the event's moment
            }

            if ($best === null || $row->validFrom() > $best->validFrom()) {
                $best = $row;
            }
        }

        return $best;
    }
}
