<?php

declare(strict_types=1);

namespace App\Domain\Billing;

use App\Domain\Exception\BillingException;
use App\Entity\Price;
use DateTimeImmutable;

/**
 * Computes the exact cost of an event per the task's pricing rules,
 * with the single final rounding to 6 digits (HALF_UP).
 */
final class PricingCalculator
{
    private const PER_MILLION = '1000000';

    /**
     * @param Price          $row     price row (per_1m_tokens | per_1m_tokens_unified)
     * @param TokenUsage     $tokens  event tokens
     * @param OffPeakPolicy  $offPeak provider discount (null — no discount)
     * @param DateTimeImmutable $eventTime event moment (UTC)
     */
    public function price(Price $row, TokenUsage $tokens, ?OffPeakPolicy $offPeak = null, ?DateTimeImmutable $eventTime = null): string
    {
        $cost = match ($row->unit()) {
            Price::UNIT_PER_TOKEN => $this->pricePerToken($row->rates(), $tokens),
            Price::UNIT_UNIFIED => Money::div(
                Money::mul((string) $tokens->total(), $this->rate($row->rates(), 'any')),
                self::PER_MILLION,
            ),
            default => throw new BillingException(sprintf('Unknown unit of measure: %s', $row->unit())),
        };

        if ($offPeak !== null && $eventTime !== null && $offPeak->applies($eventTime)) {
            $cost = Money::mul($cost, $offPeak->multiplier());
        }

        return Money::roundHalfUp($cost);
    }

    private function pricePerToken(array $rates, TokenUsage $tokens): string
    {
        $sum = '0';

        foreach ([
            'input' => $tokens->input(),
            'output' => $tokens->output(),
            'cache_read' => $tokens->cacheRead(),
            'cache_write' => $tokens->cacheWrite(),
        ] as $kind => $count) {
            $sum = Money::add(
                $sum,
                Money::div(Money::mul((string) $count, $this->rate($rates, $kind)), self::PER_MILLION),
            );
        }

        return $sum;
    }

    private function rate(array $rates, string $kind): string
    {
        if (!isset($rates[$kind]) || !\is_scalar($rates[$kind])) {
            throw new BillingException(sprintf("Price has no rate '%s'", $kind));
        }

        return (string) $rates[$kind];
    }
}
