            ->setParameter('providerCode', $providerCode)
            ->setParameter('providerRequestId', $providerRequestId)
            ->getQuery()
            ->getOneOrNullResult();
    }

    /** All events that have not been rated yet. */
    public function findUnrated(): array
    {
        return $this->createQueryBuilder('e')
            ->where('e.cost IS NULL')
            ->orderBy('e.id', 'ASC')
            ->getQuery()
            ->getResult();
    }

    /** Rated events that were billed under the given price rows. */
    public function findRatedByPriceIdIn(array $priceIds): array
    {
        if ($priceIds === []) {
            return [];
        }

        return $this->createQueryBuilder('e')
            ->where('e.cost IS NOT NULL')
            ->andWhere('e.priceId IN (:priceIds)')
            ->setParameter('priceIds', array_values(array_unique(array_map('intval', $priceIds))))
            ->orderBy('e.id', 'ASC')
            ->getQuery()
            ->getResult();
    }
}
```
Note: `IN (:priceIds)` with a plain array parameter — does DBAL 4 expand a plain array to a list with an IN clause? In DBAL 4, expanding an array parameter for IN is supported (expanding expressions like IN (:list) with array parameters are handled — DBAL 3/4: an array value as a parameter for IN is expanded into multiple parameters). Yes.

But note: a very long IN list — not a concern here.

