/**
 * Parsing and validation of price files (JSON) of the task's format:
 * sections providers/models/prices.
 */
final class PricesFileParser
{
    private const DECIMAL_PATTERN = '/^\d{1,30}(?:\.\d{1,30})?$/';

    /** Keys for each rate scheme. */
    private const RATES_BY_UNIT = [
        Price::UNIT_PER_TOKEN => ['input', 'output', 'cache_read', 'cache_write'],
        Price::UNIT_UNIFIED => ['any'],
    ];

    public function parseFile(string $file): PricesFileData
    {
        if (!is_file($file) || !is_readable($file)) {
            throw new BillingException(sprintf("File not found or unreadable: %s", $file));
        }

        $raw = file_get_contents($file);
        if ($raw === false) {
            throw new BillingException(sprintf("Unable to read file: %s", $file));
        }

        return $this->parse($raw);
    }

    public function parse(string $raw): PricesFileData
    {
        try {
            $data = json_decode($raw, true, 512, JSON_THROW_ON_ERROR);
        } catch (\JsonException $exception) {
            throw new BillingException('File is not valid JSON: '.$exception->getMessage(), 0, $exception);
        }

        if (!\is_array($data) || array_is_list($data)) {
            throw new BillingException('The root of the price file should be a JSON object');
        }

        return new PricesFileData(
            providers: $this->parseProviders(self::section($data, 'providers')),
            models: $this->parseModels(self::section($data, 'models')),
            prices: $this->parsePrices(self::section($data, 'prices')),
        );
    }

    /**
     * @return list<ProviderData>
     */
    private function parseProviders(array $items): array
    {
        $result = [];
        foreach ($items as $index => $item) {
            $ctx = sprintf('provider #%d', $index);
            if (!\is_array($item) || array_is_list($item)) {
                throw new BillingException(sprintf('%s: should be a JSON object', $ctx));
            }

            $code = self::nonEmptyString($item, 'code', $ctx);
            $name = $item['name'] ?? $code;
            if (!\is_string($name) || $name === '') {
                throw new BillingException(sprintf('%s: name should be a non-empty string', $ctx));
            }

            $result[] = new ProviderData(
                code: $code,
                name: $name,
                windowStart: ...,
                ...
            );
        }
        return $result;
    }
