private function parsePrices(array $items): array
{
    $result = [];
    foreach ($items as $index => $item) {
        $ctx = sprintf('price row #%d', $index);
        if (!\is_array($item) || array_is_list($item)) {
            throw new BillingException(sprintf('%s: should be a JSON object', $ctx));
        }

        $provider = self::nonEmptyString($item, 'provider', $ctx);
        $model = self::nonEmptyString($item, 'model', $ctx);
        $validFromRaw = self::nonEmptyString($item, 'valid_from', $ctx);
        $validFrom = Iso8601::parseUtc($validFromRaw);

        $currency = $item['currency'] ?? 'USD';
        if (!\is_string($currency) || $currency === '') {
            throw new BillingException(sprintf('%s: currency should be a non-empty string', $ctx));
        }

        $unit = self::nonEmptyString($item, 'unit', $ctx);
        if (!isset(self::RATES_BY_UNIT[$unit])) {
            throw new BillingException(sprintf('%s: unknown unit "%s" (allowed: %s)', $ctx, $unit, implode(', ', array_keys(self::RATES_BY_UNIT))));
        }

        $ratesRaw = $item['rates'] ?? null;
        if (!\is_array($ratesRaw) || array_is_list($ratesRaw)) {
            throw new BillingException(sprintf('%s: rates should be a JSON object', $ctx));
        }

        $expected = self::RATES_BY_UNIT[$unit];
        foreach ($expected as $kind) {
            if (!\array_key_exists($kind, $ratesRaw)) {
                throw new BillingException(sprintf("%s: rate '%s' missing (unit %s)", $ctx, $kind, $unit));
            }
        }
        $unexpected = array_diff(array_keys($ratesRaw), $expected);
        if ($unexpected !== []) {
            throw new BillingException(sprintf('%s: extra rates %s under unit %s', $ctx, implode(', ', array_map(strval...$unexpected)), $unit));
        }

        $rates = [];
        foreach ($expected as $kind) {
            $value = $ratesRaw[$kind];
            if (!\is_string($value) || preg_match(self::DECIMAL_PATTERN, $value) !== 1) {
                throw new BillingException(sprintf("%s: rate '%s' should be a non-negative decimal string", $ctx, $kind));
            }
            $rates[$kind] = $value;
        }

        $result[] = new PriceData($provider, $model, $validFrom, $currency, $unit, $rates);
    }
    return $result;
}

