    public function wrapInTransaction(callable $func): mixed
    {
        $this->conn->beginTransaction();

        $successful = false;

        try {
            $return = $func($this);

            $this->flush();
            $this->conn->commit();

            $successful = true;

            return $return;
        } finally {
            if (! $successful) {
                $this->close();
                if ($this->conn->isTransactionActive()) {
                    $this->conn->rollBack();
                }
            }
        }
